int main(void) {
    char s[] = "Recife";
    int n = strlen(s);
    for (int i = 0; i < n; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
    printf("%s\n", s);
    return 0;
}

